            actId = self:getConst().ACT_ID,
            stages = {
                AutoPopupConst.PopStage.STAGE_THREE,
                AutoPopupConst.PopStage.STAGE_FOUR,
            },
            check = function()
                if not self:isActivitySupported(self:getConst().ACT_ID) then return false end
                return not ignoreForTopLevelPlayer() and self:checkCanPopStage3() == true
            end,
            pop = function(_, onPopOver)
                return function()
                    self:doPopStage3(onPopOver)
                end
            end,
        }

{
            checkPoint = PopupCheckPoint.WIN_REPEAT_RANK_STAGE3_POP,
            actId = self.ACT_ID,
            stages = {AutoPopupConst.PopStage.STAGE_THREE},
            check = function()
                if not _G.amfBean("ActivityMgr"):isActSupported(self.ACT_ID) then return false end
                -- 注册式强弹会在活动数据异步到达前执行 check；此时不能进入
                -- getCurTimeRankRaceType 的时间比较。
                return self:isEnabled() and isAutoPopupLevelEffective()
                    and self:checkCanPopStage3()
            end,
            pop = function(_, onPopOver)
                return function()
                    self:popStage3(onPopOver)
                end
            end,
        }

{
            checkPoint = PopupCheckPoint.WIN_REPEAT_RANK_STAGE4_POP,
            actId = self.ACT_ID,
            stages = {AutoPopupConst.PopStage.STAGE_FOUR},
            check = function()
                if not _G.amfBean("ActivityMgr"):isActSupported(self.ACT_ID) then return false end
                return self:isEnabled() and isAutoPopupLevelEffective()
                    and not blockedForTopLevelPlayer()
                    and (self:checkCanPopMainPanel()
                        or self:checkCanPopMainPanelForGroupReward())
            end,
            pop = function(_, onPopOver)
                return function()
                    self:popMainPanel(onPopOver, 4)
                end
            end,
        }

:registerPopup({
        checkPoint = firstLoginCheckPoint,
        stages = { popStage.STAGE_TWO, popStage.STAGE_FOUR },
        check = function()
            local canPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                false
            )
            return canPopup
        end,
        creator = function(_, onPopOver)
            return self:_createAutoPopupCreator(
                onPopOver,
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                firstLoginCheckPoint,
                false
            )
        end,
    }

:registerPopup({
        checkPoint = streakBreakCheckPoint,
        stages = { popStage.STAGE_TWO, popStage.STAGE_FOUR },
        check = function()
            local canPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.STREAK_BREAK_AUTO_POP_CACHE_KEY,
                true
            )
            local firstLoginCanPopup = self:_getAutoPopupState(
                AliPayDesktopShortcutManager.FIRST_LOGIN_AUTO_POP_CACHE_KEY,
                false
            )
            local inCountdown = callIfExists(self._model, "isDeskTopVisitStreakBreak") == true
            canPopup = canPopup and not firstLoginCanPopup and inCountdown
            return canPopup
        end,
        creator = function(_, onPopOver)
            return self:_createAutoPopupCreator(
                onPopOver,
                AliPayDesktopShortcutManager.STREAK_BREAK_AUTO_POP_CACHE_KEY,
                streakBreakCheckPoint,
                true
            )
        end,
    }

:registerPopup({
        checkPoint = PopupCheckPoint.DY_FEED_SUBSCRIBE_GUIDE,
        stages = {AutoPopupConst.PopStage.STAGE_FOUR},
        check = function()
            return self:isFeedSubscribeGuideEligible()
                and self:getFeedSubscribeRequestParams() ~= nil
                and self:getFeedSubscribeStatus() ~= true
        end,
        creator = function(_, onPopOver)
            return function()
                -- 计数由 AutoPopupMgr 在 creator 调用前统一消耗；强弹直接调用抖音订阅接口。
                local params = self:getFeedSubscribeRequestParams()
                if not params then
                    safeRunCall(onPopOver)
                    return
                end

                local t2 = FeedContext.isNewUser() and 3 or 4
                self:requestFeedSubscribe(params, function()
                    safeRunCall(onPopOver)
                end, { t1 = 2, t2 = t2 })
            end
        end,
    }

:registerPopup({
        checkPoint = PopupCheckPoint.CONTINUOUS_TARGET_CHECK,
        stages = {AutoPopupConst.PopStage.STAGE_THREE},
        actId = 4042,
        check = function()
            return self:stage3OrInLevelCanPop() == true
        end,
        pop = function(stageParams, onPopOver)
            -- check/pop 收到的是强弹场景事件对象，事件数据要经 getData 取。
            local nextLevelModeData = (stageParams:getData() or {}).nextLevelModeData
            self:cleanPopReason()
            return self:_createStage3PopupCreator({
                source = 3,
                autoPlayNextLevel = nextLevelModeData and nextLevelModeData.autoPlayNextLevel or false,
            }, onPopOver)
        end,
    }
